import json
from http.server import BaseHTTPRequestHandler, HTTPServer

import numpy as np

N = 40
LAMBDA = 0.005
TOKEN = "gp-data-token-2024"

coords = np.linspace(0, 1, N)
X, Y = np.meshgrid(coords, coords)
points = np.column_stack((X.ravel(), Y.ravel()))
masks = {
    "bottom_left": (points[:, 0] <= 0.5) & (points[:, 1] <= 0.5),
    "bottom_right": (points[:, 0] > 0.5) & (points[:, 1] <= 0.5),
    "top_left": (points[:, 0] <= 0.5) & (points[:, 1] > 0.5),
    "top_right": (points[:, 0] > 0.5) & (points[:, 1] > 0.5),
}

factors = {}
for name, mask in masks.items():
    local = points[mask]
    delta = local[:, None, :] - local[None, :, :]
    squared_distances = np.sum(delta * delta, axis=2)
    covariance = np.exp(-squared_distances / 0.1)
    covariance.flat[::len(local) + 1] += LAMBDA
    factors[name] = np.linalg.cholesky(covariance)


class Handler(BaseHTTPRequestHandler):
    def respond(self, status, payload):
        data = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_POST(self):
        if self.headers.get("Authorization") != f"Bearer {TOKEN}":
            return self.respond(401, {"error": "Unauthorized"})
        if self.path != "/factorize":
            return self.respond(404, {"error": "Not found"})
        try:
            length = int(self.headers.get("Content-Length", "0"))
            body = json.loads(self.rfile.read(length))
        except (ValueError, json.JSONDecodeError):
            return self.respond(400, {"error": "Invalid JSON"})
        name = body.get("quadrant") if isinstance(body, dict) else None
        if name not in factors:
            return self.respond(400, {"error": "Invalid quadrant"})
        return self.respond(200, {"trace": float(np.trace(factors[name]))})

    def log_message(self, fmt, *args):
        print("%s - %s" % (self.address_string(), fmt % args), flush=True)


if __name__ == "__main__":
    print(f"Prepared Cholesky factors for N={N}, lambda={LAMBDA}", flush=True)
    HTTPServer(("127.0.0.1", 8050), Handler).serve_forever()
